INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Managed Services immer die gesamte IT eines Unternehmens übernehmen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Können auch teilweise sein"}, {"text": "Ja", "correct": false, "because": "Flexibel einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich Managed Services für ein Unternehmen auswähle?', 3, '[{"text": "Vertragsdetails", "correct": true, "because": "Definiert Leistung"}, {"text": "Schnellste Umsetzung", "correct": false, "because": "Qualität zählt"}, {"text": "Bürodesign", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bereiche können Managed Services abdecken?', 5, '[{"text": "IT-Support", "correct": true, "because": "Häufiger Einsatz"}, {"text": "Netzwerkmanagement", "correct": true, "because": "Sichert Betrieb"}, {"text": "Büroplanung", "correct": false, "because": "Kein Service-Fokus"}, {"text": "Marketing", "correct": false, "because": "Nicht typisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Managed Services reduzieren interne Aufwände. b) Sie sind immer teurer als Inhouse-Lösungen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kosten variieren"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich Managed Services für ein IT-System plane?', 4, '[{"text": "Serviceumfang", "correct": false, "because": "Definiert Leistung"}, {"text": "Vertragslaufzeit", "correct": false, "because": "Bestimmt Bindung"}, {"text": "Bürodeko", "correct": true, "because": "Kein Service-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Managed Services immer Cloud-basiert sind?', 2, '[{"text": "Nein", "correct": true, "because": "Auch lokal möglich"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Managed Services?', 3, '[{"text": "Effizienzsteigerung", "correct": true, "because": "Entlastet intern"}, {"text": "Schnellste Installation", "correct": false, "because": "Qualität zählt"}, {"text": "Weniger Technik", "correct": false, "because": "Nicht Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten Managed Services?', 5, '[{"text": "Kostenkontrolle", "correct": true, "because": "Feste Raten"}, {"text": "Spezialistenwissen", "correct": true, "because": "Externes Know-how"}, {"text": "Hohe Latenz", "correct": false, "because": "Nachteil"}, {"text": "Bürogestaltung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Managed Services verbessern die IT-Verfügbarkeit. b) Sie sind immer für Großunternehmen. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch für KMU"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, wenn ich Managed Services für ein Unternehmen auswähle?', 4, '[{"text": "SLA-Vertrag", "correct": false, "because": "Sichert Leistung"}, {"text": "Anbieterzuverlässigkeit", "correct": false, "because": "Bestimmt Qualität"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Service-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Managed Services immer langfristig ausgelegt?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kurzfristig möglich"}, {"text": "Ja", "correct": false, "because": "Flexibel gestaltbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile können Managed Services haben?', 4, '[{"text": "Anbieterabhängigkeit", "correct": true, "because": "Verlust an Kontrolle"}, {"text": "Vertragsbindung", "correct": true, "because": "Einschränkt Flexibilität"}, {"text": "Schnellere IT", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Managed Services nur für IT gelten. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch andere Bereiche möglich"}, {"text": "Ja", "correct": false, "because": "Zu eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um Managed Services für ein IT-System auszuwählen?', 3, '[{"text": "Anbieterkompetenz", "correct": true, "because": "Sichert Qualität"}, {"text": "Niedrigster Preis", "correct": false, "because": "Qualität wichtiger"}, {"text": "Bunte Werbung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Managed Services bieten proaktiven Support. b) Sie sind immer lokal vor Ort.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Oft remote"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte berücksichtige ich bei Managed Services?', 5, '[{"text": "Vertragsumfang", "correct": true, "because": "Definiert Leistung"}, {"text": "Supportverfügbarkeit", "correct": true, "because": "Sichert Betrieb"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich Managed Services für ein Unternehmen plane?', 3, '[{"text": "Servicequalität", "correct": false, "because": "Entscheidend für Erfolg"}, {"text": "Kostenstruktur", "correct": false, "because": "Beeinflusst Budget"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Service-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Bieten Managed Services immer 24/7 Support?', 3, '[{"text": "Nein", "correct": true, "because": "Abhängig vom Vertrag"}, {"text": "Ja", "correct": false, "because": "Nicht garantiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Managed Services die interne IT komplett ersetzen?', 2, '[{"text": "Nein", "correct": true, "because": "Ergänzung möglich"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend für Managed Services?', 4, '[{"text": "Vertragliche Vereinbarung", "correct": true, "because": "Sichert Leistung"}, {"text": "Schnellste Umsetzung", "correct": false, "because": "Qualität zählt"}, {"text": "Bürogestaltung", "correct": false, "because": "Irrelevant"}]');
